def is_expression(text):
    position = 0
    length = len(text)

    def read_number(start):
        if start >= length or text[start] not in "6789":
            return start
        position = start + 1
        while position < length and text[position] in "6789":
            position += 1
        return position

    position = read_number(position)
    if position == 0:
        return False
    while position < length:
        if text[position] not in "-*":
            return False
        next_position = read_number(position + 1)
        if next_position == position + 1:
            return False
        position = next_position
    return True

