from collections import Counter

table = []
with open("9-10.txt") as f:
    for line in f:
        table.append([int(part) for part in line.split()])
everywhere = Counter(x for row in table for x in row)
answer = 0
for a in table:
    counts = Counter(a)
    found = 0
    for x in a:
        if counts[x] == 1 and everywhere[x] - counts[x] == 160:
            found += 1
    if found > 0:
        answer += 1
print(answer)

table = []
with open("9-10.txt") as f:
    for line in f:
        table.append([int(part) for part in line.split()])
n, m = len(table), len(table[0])
answer = 0
for i in range(n):
    found = False
    for j in range(m):
        x = table[i][j]
        if table[i].count(x) != 1:
            continue
        top = True
        for di in (-1, 0, 1):
            for dj in (-1, 0, 1):
                y, z = i + di, j + dj
                inside = 0 <= y < n and 0 <= z < m
                if inside and (di, dj) != (0, 0):
                    if table[y][z] > x:
                        top = False
        if top:
            found = True
    if found:
        answer += 1
print(answer)

Блоки максимума и минимума — как для поля со стенами;
клетки, отрезанные стенами, — «X»:
=ЕСЛИ(СЧЁТ(A23;B22)=0;"X";B2+МАКС(A23;B22))
Ответ — МАКС и МИН по «угловым» клеткам блоков.
Старт D6: в клетке блока под D6 — =D6;
строки 1–5 и столбцы A–C блока — «X».

Старт T1: в клетке блока под T1 — =T1;
первая строка накапливается влево, столбец T — вниз;
внутренняя клетка: монета + МАКС(клетка справа;
клетка сверху), отрезанные клетки — «X».
Ответ — МИН и МАКС по «угловым» клеткам.

Блок «к финишу»: в клетке под T20 — =T20;
внутренняя клетка: монета + МАКС(клетка справа;
клетка снизу) — то же с МИН во втором блоке.
Ответ — сумма трёх наибольших и трёх наименьших
результатов стартов (НАИБОЛЬШИЙ, НАИМЕНЬШИЙ).

Блок числа маршрутов, старт: 1;
клетка: =ЕСЛИ(ABS(B2-A2)<=50;A18;0)
        +ЕСЛИ(ABS(B2-B1)<=50;B17;0);
недостижимые клетки — с числом 0:
=СЧЁТЕСЛИ(блок;0).

Блок «к финишу», клетка: монета + МАКС(справа;
снизу), второй блок — с МИН. Ответ — сумма двух
наибольших и двух наименьших результатов стартов.

